{"file_path":"src/address.js","content":"/**
 * Cell addresses: one or two letters naming a column, followed by one to
 * three digits naming a row of at least 1. Columns run A..Z, then AA..ZZ,
 * matching the standard spreadsheet ordering.
 */

const ADDRESS_RE = /^([A-Za-z]+)([0-9]+)$/

/**
 * Checks whether `word` (already or not yet upper-cased) names an address
 * inside the addressable range, and if so returns its column number, row
 * number, and canonical upper-cased key (with any leading zeros in the row
 * dropped).
 */
export function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return { valid: false }
  const letters = m[1].toUpperCase()
  const digits = m[2]
  if (letters.length < 1 || letters.length > 2) return { valid: false }
  if (digits.length < 1 || digits.length > 3) return { valid: false }
  const row = Number(digits)
  if (row < 1) return { valid: false }
  const col = colLettersToNum(letters)
  return { valid: true, col, row, key: letters + String(row) }
}

export function colLettersToNum(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  const c1 = letters.charCodeAt(0) - 64
  const c2 = letters.charCodeAt(1) - 64
  return 26 * c1 + c2
}

export function colNumToLetters(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  const b = ((n - 1) % 26) + 1
  const a = (n - b) / 26
  return String.fromCharCode(64 + a) + String.fromCharCode(64 + b)
}

/** Orders addresses by ascending column, then ascending row. */
export function compareAddresses(a, b) {
  const ia = parseAddress(a)
  const ib = parseAddress(b)
  if (ia.col !== ib.col) return ia.col - ib.col
  return ia.row - ib.row
}
"}

