{"file_path":"src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`). Spaces and
 * tabs are insignificant and may appear between any two tokens. Returns
 * `null` if any character does not belong to any token.
 */

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = '^*/+-=<>(),:'

export function lex(body) {
  const tokens = []
  let i = 0
  const n = body.length
  while (i < n) {
    const c = body[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c >= '0' && c <= '9') {
      let j = i + 1
      while (j < n && body[j] >= '0' && body[j] <= '9') j++
      if (j < n && body[j] === '.') {
        let k = j + 1
        if (k < n && body[k] >= '0' && body[k] <= '9') {
          while (k < n && body[k] >= '0' && body[k] <= '9') k++
          tokens.push({ type: 'NUM', value: Number(body.slice(i, k)) })
          i = k
          continue
        }
      }
      tokens.push({ type: 'NUM', value: Number(body.slice(i, j)) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < n && /[A-Za-z]/.test(body[j])) j++
      while (j < n && body[j] >= '0' && body[j] <= '9') j++
      tokens.push({ type: 'WORD', value: body.slice(i, j).toUpperCase() })
      i = j
      continue
    }
    const two = body.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(c)) {
      tokens.push({ type: c })
      i += 1
      continue
    }
    return null
  }
  return tokens
}
"}

