{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies, built from the token stream
 * produced by `lex`. Returns `null` when the grammar rejects the input.
 *
 * Precedence, loosest to tightest: comparisons, then `+`/`-`, then `*`/`/`,
 * then `^` (right associative), then a leading `+`/`-` (binds tighter than
 * `^`). Everything but `^` and the leading sign groups to the left.
 *
 * A range (`A1:B3`) is only accepted directly as a call argument.
 */

const CMP_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

export function parseFormula(tokens) {
  const st = { tokens, pos: 0 }
  const expr = parseComparison(st)
  if (expr === null) return null
  if (st.pos !== tokens.length) return null
  return expr
}

function peek(st) {
  return st.tokens[st.pos]
}

function parseComparison(st) {
  let left = parseAdditive(st)
  if (left === null) return null
  for (;;) {
    const t = peek(st)
    if (!t || !CMP_OPS.has(t.type)) break
    st.pos++
    const right = parseAdditive(st)
    if (right === null) return null
    left = { type: 'BinOp', op: t.type, left, right }
  }
  return left
}

function parseAdditive(st) {
  let left = parseMultiplicative(st)
  if (left === null) return null
  for (;;) {
    const t = peek(st)
    if (!t || (t.type !== '+' && t.type !== '-')) break
    st.pos++
    const right = parseMultiplicative(st)
    if (right === null) return null
    left = { type: 'BinOp', op: t.type, left, right }
  }
  return left
}

function parseMultiplicative(st) {
  let left = parsePower(st)
  if (left === null) return null
  for (;;) {
    const t = peek(st)
    if (!t || (t.type !== '*' && t.type !== '/')) break
    st.pos++
    const right = parsePower(st)
    if (right === null) return null
    left = { type: 'BinOp', op: t.type, left, right }
  }
  return left
}

function parsePower(st) {
  const base = parseUnary(st)
  if (base === null) return null
  const t = peek(st)
  if (t && t.type === '^') {
    st.pos++
    const right = parsePower(st)
    if (right === null) return null
    return { type: 'BinOp', op: '^', left: base, right }
  }
  return base
}

function parseUnary(st) {
  const t = peek(st)
  if (t && (t.type === '+' || t.type === '-')) {
    st.pos++
    const operand = parseUnary(st)
    if (operand === null) return null
    return { type: 'Unary', op: t.type, expr: operand }
  }
  return parsePrimary(st)
}

function parsePrimary(st) {
  const t = peek(st)
  if (!t) return null
  if (t.type === 'NUM') {
    st.pos++
    return { type: 'Num', v: t.value }
  }
  if (t.type === '(') {
    st.pos++
    const inner = parseComparison(st)
    if (inner === null) return null
    const close = peek(st)
    if (!close || close.type !== ')') return null
    st.pos++
    return inner
  }
  if (t.type === 'WORD') {
    st.pos++
    const word = t.value
    const nt = peek(st)
    if (nt && nt.type === '(') {
      st.pos++
      const args = []
      const first = peek(st)
      if (first && first.type === ')') {
        st.pos++
      } else {
        for (;;) {
          const arg = parseArgument(st)
          if (arg === null) return null
          args.push(arg)
          const sep = peek(st)
          if (sep && sep.type === ',') {
            st.pos++
            continue
          }
          if (sep && sep.type === ')') {
            st.pos++
            break
          }
          return null
        }
      }
      return { type: 'Call', name: word, args }
    }
    if (word === 'TRUE') return { type: 'Bool', v: true }
    if (word === 'FALSE') return { type: 'Bool', v: false }
    return { type: 'Addr', word }
  }
  return null
}

function parseArgument(st) {
  const t = peek(st)
  if (t && t.type === 'WORD') {
    const t2 = st.tokens[st.pos + 1]
    if (t2 && t2.type === ':') {
      const a = t.value
      st.pos += 2
      const t3 = peek(st)
      if (!t3 || t3.type !== 'WORD') return null
      st.pos++
      return { type: 'Range', a, b: t3.value }
    }
  }
  return parseComparison(st)
}
"}

