  let left = parsePower(st)
  if (left === null) return null
  for (;;) {
    const t = peek(st)
    if (!t || (t.type !== '*' && t.type !== '/')) break
    st.pos++
    const right = parsePower(st)
    if (right === null) return null
    left = { type: 'BinOp', op: t.type, left, right }
  }
  return left
