{"file_path":"src/values.js","content":"/**
 * Runtime values: a number, text, a boolean, or an error token.
 */

export const num = (v) => ({ t: 'num', v })
export const text = (v) => ({ t: 'text', v })
export const bool = (v) => ({ t: 'bool', v })
export const err = (v) => ({ t: 'err', v })

export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

/** Reads a literal cell body (never a formula) as a value. */
export function parseLiteral(s) {
  if (s === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERROR_TOKENS.has(s)) return err(s)
  return text(s)
}

/** Coerces a value to a number in an arithmetic position, or its error. */
export function toNumberValue(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  if (v.t === 'text') return err('#VALUE!')
  return v // already an error
}

/** Wraps a computed number, turning a non-finite result into #DIV/0!. */
export function finiteOrDivZero(n) {
  return Number.isFinite(n) ? num(n) : err('#DIV/0!')
}

function rank(v) {
  return v.t === 'num' ? 0 : v.t === 'text' ? 1 : 2
}

/** Orders two non-error values: numbers < texts < booleans, ties broken within a kind. */
export function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 'num' || a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

export function formatValue(v) {
  if (v.t === 'num') return formatNum(v.v)
  if (v.t === 'text') return v.v
  if (v.t === 'bool') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

function formatNum(n) {
  return String(Number(n.toPrecision(10)))
}
"}

