    if (cache.has(key)) return cache.get(key)
    if (stack.has(key)) return err('#CYCLE!')
    const cell = cells.get(key)
    stack.add(key)
    const result = cell.isFormula
      ? cell.ast === null
        ? err('#ERR!')
        : evalNode(cell.ast)
      : cell.literal
    stack.delete(key)
    cache.set(key, result)
    return result
  }

  function readAddress(word) {
    const info = parseAddress(word)
    if (!info.valid) return err('#REF!')
    if (!cells.has(info.key)) return num(0)
    return evaluateCell(info.key)
  }

  function flattenRange(rangeNode) {
    const a = parseAddress(rangeNode.a)
    const b = parseAddress(rangeNode.b)
    if (!a.valid || !b.valid) return [err('#REF!')]
    const colLo = Math.min(a.col, b.col)
    const colHi = Math.max(a.col, b.col)
    const rowLo = Math.min(a.row, b.row)
    const rowHi = Math.max(a.row, b.row)
    const values = []
    for (let c = colLo; c <= colHi; c++) {
      for (let r = rowLo; r <= rowHi; r++) {
        values.push(readAddress(colNumToLetters(c) + r))
      }
    }
    return values
  }

  // Evaluates an argument that a scalar-taking function (ABS, IF) expects.
  function evalScalarArg(node) {
    if (node.type === 'Range') {
      const values = flattenRange(node)
      for (const v of values) if (v.t === 'err') return v
      if (values.length !== 1) return err('#VALUE!')
      return values[0]
    }
    return evalNode(node)
  }

  function evalArith(op, leftVal, rightVal) {
    if (leftVal.t === 'err') return leftVal
    const ln = toNumberValue(leftVal)
    if (ln.t === 'err') return ln
    if (rightVal.t === 'err') return rightVal
    const rn = toNumberValue(rightVal)
    if (rn.t === 'err') return rn
    switch (op) {
      case '+':
        return finiteOrDivZero(ln.v + rn.v)
      case '-':
        return finiteOrDivZero(ln.v - rn.v)
      case '*':
        return finiteOrDivZero(ln.v * rn.v)
      case '/':
        if (rn.v === 0) return err('#DIV/0!')
        return finiteOrDivZero(ln.v / rn.v)
      case '^':
        return finiteOrDivZero(Math.pow(ln.v, rn.v))
    }
  }

  function evalComparison(op, leftVal, rightVal) {
    if (leftVal.t === 'err') return leftVal
    if (rightVal.t === 'err') return rightVal
    const c = compareValues(leftVal, rightVal)
    switch (op) {
      case '=':
        return bool(c === 0)
      case '<>':
        return bool(c !== 0)
      case '<':
        return bool(c < 0)
      case '<=':
        return bool(c <= 0)
      case '>':
        return bool(c > 0)
      case '>=':
        return bool(c >= 0)
    }
  }

  function evalCall(node) {
    const name = node.name
    const argc = node.args.length
    if (name in KNOWN_ARITY || LIST_FUNCS.has(name)) {
      if (name in KNOWN_ARITY) {
        if (argc !== KNOWN_ARITY[name]) return err('#ERR!')
      } else if (argc < 1) {
        return err('#ERR!')
      }
    } else {
      return err('#NAME?')
    }

    if (name === 'ABS') {
      const v = evalScalarArg(node.args[0])
      if (v.t === 'err') return v
      const n = toNumberValue(v)
      if (n.t === 'err') return n
      return finiteOrDivZero(Math.abs(n.v))
    }

    if (name === 'IF') {
      const cond = evalScalarArg(node.args[0])
      if (cond.t === 'err') return cond
      let truth
      if (cond.t === 'bool') truth = cond.v
      else if (cond.t === 'num') truth = cond.v !== 0
      else return err('#VALUE!')
      return truth ? evalScalarArg(node.args[1]) : evalScalarArg(node.args[2])
    }

    // SUM, MIN, MAX, AVG, COUNT
    const contributions = []
    for (const arg of node.args) {
      if (arg.type === 'Range') contributions.push(...flattenRange(arg))
      else contributions.push(evalNode(arg))
    }

    if (name === 'COUNT') {
      for (const v of contributions) if (v.t === 'err') return v
      let count = 0
      for (const v of contributions) if (v.t === 'num') count++
      return num(count)
    }

    const nums = []
    for (const v of contributions) {
      const n = toNumberValue(v)
      if (n.t === 'err') return n
      nums.push(n.v)
    }
    if (name === 'SUM') return finiteOrDivZero(nums.reduce((a, b) => a + b, 0))
    if (name === 'MIN') return finiteOrDivZero(Math.min(...nums))
    if (name === 'MAX') return finiteOrDivZero(Math.max(...nums))
    // AVG
    return finiteOrDivZero(nums.reduce((a, b) => a + b, 0) / nums.length)
  }

  function evalNode(node) {
    switch (node.type) {
      case 'Num':
        return num(node.v)
      case 'Bool':
        return bool(node.v)
      case 'Addr':
        return readAddress(node.word)
      case 'Unary': {
        const v = evalNode(node.expr)
        if (v.t === 'err') return v
        const n = toNumberValue(v)
        if (n.t === 'err') return n
        return finiteOrDivZero(node.op === '-' ? -n.v : n.v)
      }
      case 'BinOp': {
        const left = evalNode(node.left)
        const right = evalNode(node.right)
        return CMP_OPS.has(node.op) ? evalComparison(node.op, left, right) : evalArith(node.op, left, right)
      }
      case 'Call':
        return evalCall(node)
      default:
        return err('#ERR!')
    }
  }

  return { evaluateCell }
}

/** Collects the addresses a parsed formula names directly, ranges expanded. */
export function collectAddresses(ast, set) {
  if (ast === null) return
  switch (ast.type) {
    case 'Num':
    case 'Bool':
      return
    case 'Addr': {
      const info = parseAddress(ast.word)
      if (info.valid) set.add(info.key)
      return
    }
    case 'Unary':
      collectAddresses(ast.expr, set)
      return
    case 'BinOp':
      collectAddresses(ast.left, set)
      collectAddresses(ast.right, set)
      return
    case 'Call':
      for (const arg of ast.args) {
        if (arg.type === 'Range') addRangeAddresses(arg, set)
        else collectAddresses(arg, set)
      }
      return
  }
}

function addRangeAddresses(rangeNode, set) {
  const a = parseAddress(rangeNode.a)
  const b = parseAddress(rangeNode.b)
  if (!a.valid || !b.valid) return
  const colLo = Math.min(a.col, b.col)
  const colHi = Math.max(a.col, b.col)
  const rowLo = Math.min(a.row, b.row)
  const rowHi = Math.max(a.row, b.row)
  for (let c = colLo; c <= colHi; c++) {
    for (let r = rowLo; r <= rowHi; r++) {
      set.add(colNumToLetters(c) + r)
    }
  }
}
"}

