{"file_path":"src/sheet.js","content":"/**
 * Parses a sheet from raw text into a map of address -> cell, validating
 * addresses and rejecting duplicates. Throws a `SheetError` carrying the
 * offending line number on the first problem found, scanning top to bottom.
 */

import { parseAddress } from './address.js'
import { lex } from './lexer.js'
import { parseFormula } from './parser.js'
import { parseLiteral } from './values.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  lines.forEach((line, idx) => {
    const lineNo = idx + 1
    let i = 0
    while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
    const rest = line.slice(i)
    if (rest === '' || rest[0] === '#') return

    let k = 0
    while (k < rest.length && rest[k] !== ' ' && rest[k] !== '\t') k++
    const addrRaw = rest.slice(0, k)
    let afterAddr = rest.slice(k)

    let m = 0
    while (m < afterAddr.length && (afterAddr[m] === ' ' || afterAddr[m] === '\t')) m++
    const content = afterAddr.slice(m)

    const info = parseAddress(addrRaw)
    if (!info.valid) throw new SheetError(lineNo, `invalid cell address ${addrRaw.toUpperCase()}`)
    if (cells.has(info.key)) throw new SheetError(lineNo, `cell ${info.key} is declared twice`)

    const isFormula = content.startsWith('=')
    let ast = null
    let literal = null
    if (isFormula) {
      const tokens = lex(content.slice(1))
      ast = tokens === null ? null : parseFormula(tokens)
    } else {
      literal = parseLiteral(content)
    }

    cells.set(info.key, { content, isFormula, ast, literal, line: lineNo })
  })

  return cells
}
"}

