{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { createEvaluator, collectAddresses } from './evaluator.js'
import { formatValue } from './values.js'
import { compareAddresses } from './address.js'

function fail(message, code) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(code)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps', 2)
  }
  const mode = argv[0]

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(`line ${e.line}: ${e.message}`, 2)
    throw e
  }

  const keys = [...cells.keys()].sort(compareAddresses)
  const lines = []

  if (mode === 'values') {
    const { evaluateCell } = createEvaluator(cells)
    for (const key of keys) {
      lines.push(`${key}=${formatValue(evaluateCell(key))}`)
    }
  } else {
    for (const key of keys) {
      const cell = cells.get(key)
      const set = new Set()
      if (cell.isFormula) collectAddresses(cell.ast, set)
      const addrs = [...set].sort(compareAddresses)
      lines.push(`${key}:` + addrs.map((a) => ` ${a}`).join(''))
    }
  }

  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
}

main()
"}

